 if(select sum(amount_minor)from public.employee_salary_component_values where company_id=c and assignment_id=public.salary_assignment_at(c,e,'2099-01-01'))<>6500000 then raise exception 'FAIL preset edit rewrote existing pay';end if;
 perform public.save_employee(c,p||'{"employeeCode":"NEW_SUP","designation":"Supervisor"}');
 perform public.import_client_employees(c,jsonb_build_array(jsonb_build_object('employeeCode','CSVROLE','employeeName','CSV Person','joiningDate','2026-07-01','clientStatus','Active','dateOfBirth','','gender','','maritalStatus','','phone','','department','','designation','Manager','workLocation','','state','','counterCode','','counterName','','accountNumber','','ifscCode','','pan','','uan','','esicNumber','','amounts','{"basic":1000000,"da":0,"hra":0,"other":0}'::jsonb,'salaryEffectiveFrom','2026-07-01','salaryReference','{"grossMinor":1000000,"pfMinor":null,"esiMinor":null,"ctcMinor":null}'::jsonb)));
 if(select sum(v.amount_minor)from public.employees emp join public.employee_salary_assignments a on a.employee_id=emp.id and a.company_id=c join public.employee_salary_component_values v on v.assignment_id=a.id and v.company_id=c where emp.company_id=c and emp.employee_code='CSVROLE')<>1000000 then raise exception 'FAIL explicit CSV salary collided with preset';end if;
 perform public.import_attendance_with_employees(c,'[{"employeeId":"ATTROLE","date":"2026-07-01","status":"P"}]','[{"employeeCode":"ATTROLE","employeeName":"Attendance Role","joiningDate":"2026-07-01","designation":"Team Lead"}]','Role import');
 if not exists(select 1 from public.attendance_records a join public.employees emp on emp.id=a.employee_id and emp.company_id=c where a.company_id=c and emp.employee_code='ATTROLE'and a.status='Present')then raise exception 'FAIL raw P alias';end if;
 select id into hr_employee from public.employees where company_id=c and employee_code='ATTROLE';
 perform public.save_attendance(c,jsonb_build_array(jsonb_build_object('employeeId',hr_employee,'date','2026-07-02','status','A')),'Alias fixture',false);
 if not exists(select 1 from public.attendance_records where employee_id=hr_employee and company_id=c and date='2026-07-02'and status='Absent')then raise exception 'FAIL raw A alias';end if;
