 if(select sum(amount_minor)from public.employee_salary_component_values where company_id=c and assignment_id=public.salary_assignment_at(c,hr_employee,'2026-07-01'))<>2800000 then raise exception 'FAIL HR approved-preset onboarding';end if;
 select jsonb_agg(jsonb_build_object('employeeId',emp.id,'date',d::date,'status','P'))into batch from public.employees emp cross join generate_series('2026-07-01'::date,'2026-07-31'::date,interval '1 day')d where emp.company_id=c and not exists(select 1 from public.attendance_records a where a.company_id=c and a.employee_id=emp.id and a.date=d::date);
 perform public.save_attendance(c,batch,'Full role fixture',false);perform public.finalize_attendance(c,'2026-07-01');
